    [{ text: "Mistral-7B-Instruct-v0.3", options: { ...modelOpts } }, { text: "59.15 ± 0.10", options: { ...cellOpts } }, { text: "35.90 ± 4.54", options: { ...cellOpts } }, { text: "8.94 ± 1.24", options: { ...cellOpts } }, { text: "21.60 ± 0.17", options: { ...cellOpts } }],
    [{ text: "  └ FP8", options: { ...modelFp8 } }, { text: "58.77 ± 0.13", options: { ...cellFp8 } }, { text: "32.20 ± 4.02", options: { ...cellFp8 } }, { text: "7.68 ± 1.23", options: { ...cellFp8 } }, { text: "22.72 ± 0.19", options: { ...cellFp8 } }],
