const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "AI Security Research";
pres.title = "Auditing Model Substitution in LLM APIs";

// Color palette — Midnight Executive with security accent
const C = {
  navy: "0F1B2D",
  darkBg: "141E30",
  cardBg: "1C2940",
  cardBg2: "1A2538",
  accent: "3B82F6",    // bright blue
  accentAlt: "60A5FA",
  danger: "EF4444",
  warn: "F59E0B",
  success: "10B981",
  white: "FFFFFF",
  light: "E2E8F0",
  muted: "94A3B8",
  bodyText: "CBD5E1",
  subtle: "475569",
};

const FONT_H = "Georgia";
const FONT_B = "Calibri";

const fig1 = path.resolve("/app/benchmark/assets/figure_1.jpg");
const fig5 = path.resolve("/app/benchmark/assets/figure_5.jpg");

function makeShadow() {
  return { type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.25 };
}

// ── SLIDE 1: Title ──
{
  const s = pres.addSlide();
  s.background = { color: C.navy };
  // Top accent bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });
  s.addText("Are You Getting What You Pay For?", {
    x: 0.8, y: 1.0, w: 8.4, h: 1.0,
    fontSize: 36, fontFace: FONT_H, color: C.white, bold: true, align: "left", margin: 0,
  });
  s.addText("Auditing Model Substitution in LLM APIs", {
    x: 0.8, y: 1.95, w: 8.4, h: 0.7,
    fontSize: 22, fontFace: FONT_H, color: C.accentAlt, align: "left", margin: 0,
  });
  s.addShape(pres.shapes.RECTANGLE, { x: 0.8, y: 2.85, w: 2.2, h: 0.04, fill: { color: C.accent } });
  s.addText("Why Software Tests Fail and Hardware Attestation Wins", {
    x: 0.8, y: 3.1, w: 8.4, h: 0.5,
    fontSize: 16, fontFace: FONT_B, color: C.bodyText, align: "left", margin: 0,
  });
  s.addText("Based on arXiv:2504.04715", {
    x: 0.8, y: 3.7, w: 4, h: 0.35,
    fontSize: 11, fontFace: FONT_B, color: C.muted, italic: true, align: "left", margin: 0,
  });
  s.addText("For ML Researchers  •  AI Security Practitioners  •  Cloud Infrastructure Engineers", {
    x: 0.8, y: 4.8, w: 8.4, h: 0.35,
    fontSize: 10, fontFace: FONT_B, color: C.subtle, align: "left", margin: 0,
  });
}

// ── SLIDE 2: Substitution Threat ──
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };
  s.addText("The Model Substitution Problem", {
    x: 0.7, y: 0.35, w: 8.6, h: 0.6,
    fontSize: 28, fontFace: FONT_H, color: C.white, bold: true, margin: 0,
  });
  s.addText("Economic Incentives Drive Covert Swaps", {
    x: 0.7, y: 0.9, w: 8.6, h: 0.35,
    fontSize: 13, fontFace: FONT_B, color: C.accentAlt, margin: 0,
  });

  // Left: explanation
  s.addText([
    { text: "Providers charge for access to specific models (e.g., Llama-3-70B), but the black-box nature of APIs means users have no guarantee the advertised model is actually being served.", options: { fontSize: 12, color: C.bodyText, breakLine: true, paraSpaceAfter: 8 } },
    { text: "Formal Framework:", options: { fontSize: 12, color: C.accentAlt, bold: true, breakLine: true, paraSpaceAfter: 4 } },
    { text: "H₀: P_actual = P_spec  vs  H₁: P_actual ≠ P_spec", options: { fontSize: 11, fontFace: "Consolas", color: C.warn, breakLine: true, paraSpaceAfter: 4 } },
    { text: "Can an auditor distinguish the specified model's distribution from an alternative, given only API query access?", options: { fontSize: 11, color: C.muted, italic: true } },
  ], { x: 0.7, y: 1.5, w: 4.6, h: 2.5, fontFace: FONT_B, valign: "top", margin: 0 });

  // Right: 4 substitution types as cards
  const types = [
    { label: "Smaller Model", desc: "e.g., 8B instead of 70B", col: C.danger },
    { label: "Quantized Variant", desc: "FP8/INT8 instead of FP16", col: C.warn },
    { label: "Fine-tuned Version", desc: "Updated or adapted weights", col: C.accent },
    { label: "Different Family", desc: "Entirely different architecture", col: C.success },
  ];
  types.forEach((t, i) => {
    const yy = 1.5 + i * 0.85;
    s.addShape(pres.shapes.RECTANGLE, { x: 5.8, y: yy, w: 3.7, h: 0.7, fill: { color: C.cardBg }, shadow: makeShadow() });
    s.addShape(pres.shapes.RECTANGLE, { x: 5.8, y: yy, w: 0.07, h: 0.7, fill: { color: t.col } });
    s.addText(t.label, { x: 6.05, y: yy + 0.08, w: 3.3, h: 0.3, fontSize: 12, fontFace: FONT_B, color: C.white, bold: true, margin: 0 });
    s.addText(t.desc, { x: 6.05, y: yy + 0.35, w: 3.3, h: 0.25, fontSize: 10, fontFace: FONT_B, color: C.muted, margin: 0 });
  });
}

// ── SLIDE 3: Quantization Benchmark Drop ──
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };
  s.addText("FP8 Quantization Preserves Most Accuracy", {
    x: 0.7, y: 0.3, w: 8.6, h: 0.55,
    fontSize: 26, fontFace: FONT_H, color: C.white, bold: true, margin: 0,
  });
  s.addText("Making Substitution Hard to Detect — Performance drops are often within error bars", {
    x: 0.7, y: 0.8, w: 8.6, h: 0.3,
    fontSize: 11, fontFace: FONT_B, color: C.muted, margin: 0,
  });

  const headerOpts = { fill: { color: C.accent }, color: C.white, bold: true, fontSize: 9, fontFace: FONT_B, align: "center", valign: "middle" };
  const cellOpts = { fontSize: 9, fontFace: FONT_B, color: C.bodyText, align: "center", valign: "middle" };
  const cellFp8 = { fontSize: 9, fontFace: FONT_B, color: C.muted, align: "center", valign: "middle", fill: { color: C.cardBg } };
  const modelOpts = { fontSize: 9, fontFace: FONT_B, color: C.white, bold: true, align: "left", valign: "middle" };
  const modelFp8 = { fontSize: 9, fontFace: FONT_B, color: C.accentAlt, align: "left", valign: "middle", fill: { color: C.cardBg } };

  const rows = [
    [
      { text: "Model", options: { ...headerOpts, align: "left" } },
      { text: "MMLU", options: headerOpts },
      { text: "GSM8K", options: headerOpts },
      { text: "MATH", options: headerOpts },
