const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "AI Security Research";
pres.title = "Auditing Model Substitution in LLM APIs";

// Color palette — Midnight Executive with security accent
const C = {
  navy: "0F1B2D",
  darkBg: "141E30",
  cardBg: "1C2940",
  cardBg2: "1A2538",
  accent: "3B82F6",    // bright blue
  accentAlt: "60A5FA",
  danger: "EF4444",
  warn: "F59E0B",
  success: "10B981",
  white: "FFFFFF",
  light: "E2E8F0",
  muted: "94A3B8",
  bodyText: "CBD5E1",
  subtle: "475569",
};

const FONT_H = "Georgia";
const FONT_B = "Calibri";

const fig1 = path.resolve("/app/benchmark/assets/figure_1.jpg");
const fig5 = path.resolve("/app/benchmark/assets/figure_5.jpg");

function makeShadow() {
  return { type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.25 };
}

// ── SLIDE 1: Title ──
{
  const s = pres.addSlide();
  s.background = { color: C.navy };
  // Top accent bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.accent } });
  s.addText("Are You Getting What You Pay For?", {
    x: 0.8, y: 1.0, w: 8.4, h: 1.0,
    fontSize: 36, fontFace: FONT_H, color: C.white, bold: true, align: "left", margin: 0,
  });
  s.addText("Auditing Model Substitution in LLM APIs", {
    x: 0.8, y: 1.95, w: 8.4, h: 0.7,
    fontSize: 22, fontFace: FONT_H, color: C.accentAlt, align: "left", margin: 0,
  });
  s.addShape(pres.shapes.RECTANGLE, { x: 0.8, y: 2.85, w: 2.2, h: 0.04, fill: { color: C.accent } });
  s.addText("Why Software Tests Fail and Hardware Attestation Wins", {
    x: 0.8, y: 3.1, w: 8.4, h: 0.5,
    fontSize: 16, fontFace: FONT_B, color: C.bodyText, align: "left", margin: 0,
  });
  s.addText("Based on arXiv:2504.04715", {
    x: 0.8, y: 3.7, w: 4, h: 0.35,
    fontSize: 11, fontFace: FONT_B, color: C.muted, italic: true, align: "left", margin: 0,
  });
  s.addText("For ML Researchers  •  AI Security Practitioners  •  Cloud Infrastructure Engineers", {
    x: 0.8, y: 4.8, w: 8.4, h: 0.35,
    fontSize: 10, fontFace: FONT_B, color: C.subtle, align: "left", margin: 0,
  });
}

// ── SLIDE 2: Substitution Threat ──
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };
  s.addText("The Model Substitution Problem", {
    x: 0.7, y: 0.35, w: 8.6, h: 0.6,
